"""
    Build valid list of run arguments for spk_run.py based on a settings dict.
    """
def run_args_from_settings(settings: Any) -> object {
    run_args = [
        settings["script"],
        settings["mode"],
        settings["representation"],
        settings["dataset"],
        settings["dbpath"],
        settings["modeldir"],
        "--split",
        *settings["split"],
        "--property",
        settings["property"],
        "--max_epochs",
        settings["max_epochs"],
        "--checkpoint_interval",
        settings["checkpoint_interval"],
        "--keep_n_checkpoints",
        settings["keep_n_checkpoints"]
    ];
    if (settings["derivative"] is not None) {
        run_args += ["--derivative", settings["derivative"]];
        if settings["negative_dr"] {
            run_args += ["--negative_dr"];
        }
    }
    if (settings["contributions"] is not None) {
        run_args += ["--contributions", settings["contributions"]];
    }
    if (settings["output_module"] is not None) {
        run_args += ["--output_module", settings["output_module"]];
    }
    run_args = [str(arg) for arg in run_args];
    return run_args;
}

""" Index where we should insert t in sorted arr. If t exists, then
    we can return the left (left=True) or right (left=False) side of
    the dups range. """
def bsearch_ins_pos(arr: Any, t: Any, left: Any) -> object {
    low = 0;
    high = len(arr);
    while (low < high) {
        mid = low + ((high - low) // 2);
        if (arr[mid] < t) {
            low = mid + 1;
        } elif (arr[mid] > t) {
            high = mid;
        } elif left {
            high = mid;
        } else {
            low = mid + 1;
        }
    }
    return low;
}

